    ru: ['2.5.433 — Знак вентиляции Надзирателя показывает облачко и стрелку, без английского слова.'],
    es: ['2.5.433 — El aviso de ventilación del Supervisor muestra una nube y una flecha, sin la palabra en inglés.'],
