    'fa-AF': ['در گوشی، کمک واژه‌های لمس است.'],
    rw: ['Kuri telefoni, Ubufasha bugira amagambo yo gukanda.'],
    ti: ['ኣብ ስልኪ ሓገዝ ቃላት ምጥዋቕ እዩ።'],
