    'fa-AF': ['بکس و نوار مثل یک بازی واقعی اند: خانه‌های مربع با شمارش، و چیزها به نوار پرواز می‌کنند.'],
    rw: ['Agasaho n\'umurongo bisa nk\'umukino w\'ukuri: uduce dufite ingano, kandi ibintu biruruka mu murongo.'],
